/// The extended error codes this specification declares (SPEC §7.3 item 9,
/// §8.5), in declaration order. Empty when it declares none.
pub const ERROR_CODES: &[crate::DeclaredErrorCode] = &[error_codes::CURSOR_INVALID];
/// One constant per extended error code this specification declares
/// (SPEC §7.3 item 9), named for its local part.
///
/// Emit these rather than a string literal: the code is read from the
/// specification, so it cannot name a code the specification never
/// declared.
pub mod error_codes {
    /// `vta/witness/list:cursorInvalid`
    ///
    /// The supplied `cursor` cannot be honoured — expired, malformed, or issued against vault state no longer recognised. Consumers SHOULD retry from the first page without a cursor.
    ///
    /// Declared `retryable: true`.
    pub const CURSOR_INVALID: crate::DeclaredErrorCode = crate::DeclaredErrorCode {
        code: "vta/witness/list:cursorInvalid",
        retryable: true,
        details_schema: ::core::option::Option::None,
    };
}
